# Root-owned bounded observer. Starts schedule child under 256MiB transport job,
# retains its original handle, & waits for launcher/collector release proof.
[CmdletBinding()]
param(
  [Parameter(Mandatory)][string]$StageRoot,
  [Parameter(Mandatory)][string]$PlanPath,
  [Parameter(Mandatory)][ValidatePattern('^[0-9a-fA-F]{64}$')][string]$ExpectedPlanSha256,
  [Parameter(Mandatory)][string]$PreflightPath,
  [Parameter(Mandatory)][ValidatePattern('^[0-9a-fA-F]{64}$')][string]$ExpectedPreflightSha256,
  [Parameter(Mandatory)][string]$ControlsReceiptPath,
  [Parameter(Mandatory)][ValidatePattern('^[0-9a-fA-F]{64}$')][string]$ExpectedControlsReceiptSha256,
  [Parameter(Mandatory)][string]$TransportHelperPath,
  [Parameter(Mandatory)][ValidatePattern('^[0-9a-fA-F]{64}$')][string]$TransportHelperSha256,
  [Parameter(Mandatory)][string]$OutputPath,
  [ValidateRange(60,1100)][int]$DeadlineSeconds=1100
)
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
function Require([bool]$ok,[string]$message){if(-not $ok){throw $message}}
function Full([string]$path){return [IO.Path]::GetFullPath($path)}
function Hash([string]$path){return (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant()}
function Read-BoundedJson([string]$path){$item=Get-Item -LiteralPath $path -Force;Require (-not $item.PSIsContainer -and ($item.Attributes -band [IO.FileAttributes]::ReparsePoint)-eq 0 -and $item.Length -le 2097152) "bounded JSON rejected: $path";return [IO.File]::ReadAllText($item.FullName)|ConvertFrom-Json}
function Write-FreshJson([string]$path,[object]$value){$full=Full $path;Require (-not(Test-Path -LiteralPath $full)) "observer receipt must be fresh: $full";$parent=Split-Path -Parent $full;if(-not(Test-Path -LiteralPath $parent -PathType Container)){[IO.Directory]::CreateDirectory($parent)|Out-Null};$tmp="$full.$([guid]::NewGuid().ToString('N')).tmp";$bytes=[Text.Encoding]::UTF8.GetBytes(($value|ConvertTo-Json -Depth 16)+"`r`n");$stream=[IO.File]::Open($tmp,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$stream.Write($bytes,0,$bytes.Length);$stream.Flush($true)}finally{$stream.Dispose()};[IO.File]::Move($tmp,$full)}
function Quote([string]$value){if($value -notmatch '[\s"]'){return $value};return '"'+$value.Replace('"','\"')+'"'}
function StreamProof([string]$path){$item=Get-Item -LiteralPath $path -Force;Require (-not $item.PSIsContainer -and ($item.Attributes -band [IO.FileAttributes]::ReparsePoint)-eq 0 -and $item.Length -le 8388608) "schedule stream bound/reparse failure: $path";return [ordered]@{path=$item.FullName;bytes=[int64]$item.Length;sha256=(Hash $item.FullName)}}
$output=Full $OutputPath;$stage=Full $StageRoot;$planFile=Full $PlanPath;$preflight=Full $PreflightPath;$controls=Full $ControlsReceiptPath;$transport=Full $TransportHelperPath;$scheduleProcess=$null;$scheduleHandle=[IntPtr]::Zero;$scheduleHandleAcquired=$false;$scheduleTerminal=$false;[uint32]$scheduleRaw=259;$scheduleSigned=$null;$scheduleExit=$null;$scheduleExitIdentity=$false;$stdoutState=$null;$stderrState=$null;$stdoutProof=$null;$stderrProof=$null;$streamsSealed=$false;$job=$null;$initial=$null;$final=$null;$failure=$null;$status='held';$launcher=$null;$collector=$null;$coordinator=$null;$schedulerState=$null;$schedulerRunning=$null;$watch=[Diagnostics.Stopwatch]::StartNew();$scheduleStartedAt=$null;$cleanup=$null;$cleanupProof=$false;$schedulerTerminal=$false
try {
  Require (Test-Path -LiteralPath $stage -PathType Container) "stage missing: $stage";Require (Test-Path -LiteralPath $planFile -PathType Leaf) "plan missing: $planFile";Require ($planFile -ceq (Full (Join-Path $stage 'one-run-plan-r8.json'))) 'observer plan must be staged one-run-plan-r8.json';Require (Test-Path -LiteralPath $preflight -PathType Leaf) 'observer production preflight missing';Require ([IO.Path]::GetFileName($preflight) -ceq 'entry-native-r8.ps1') 'observer preflight filename mismatch';Require ((Hash $preflight) -ceq $ExpectedPreflightSha256.ToLowerInvariant()) 'observer preflight SHA-256 mismatch';$plan=Read-BoundedJson $planFile;$pins=Read-BoundedJson (Join-Path $stage 'source-pins-r8.json');$planSha=Hash $planFile;Require ($planSha -ceq $ExpectedPlanSha256.ToLowerInvariant()) 'observer plan SHA-256 mismatch';Require ([string]$pins.sourcePlanSha256 -ceq $planSha) 'observer source plan SHA-256 mismatch';Require ([string]$plan.schema -eq 'sr0-display-selfjob-v4-fresh-one-run-r8') 'observer plan schema mismatch';Require ([int64]$plan.aggregateJobMemoryLimitBytes -eq 1073741824) 'observer native aggregate memory bound mismatch';Require ([int]$plan.deadlineSeconds -eq 900 -and [int]$plan.pollSeconds -eq 1) 'observer native deadline/poll mismatch';Require ([bool]$plan.noActivate -and [bool]$plan.noResources) 'observer interaction guards missing';Require (-not [bool]$plan.qualificationClaim -and [int]$plan.nativeActions -eq 0) 'observer plan qualification/native flags invalid';Require (@($plan.requiredControlReceipts).Count -eq 1) 'observer requires one production controls receipt';$expectedControls=Full (Join-Path ([string]$plan.controlReceiptRoot) ([string]$plan.requiredControlReceipts[0]));Require ($controls -ceq $expectedControls) 'observer controls receipt path mismatch';Require (Test-Path -LiteralPath $controls -PathType Leaf) 'observer controls receipt missing';Require ((Hash $controls) -ceq $ExpectedControlsReceiptSha256.ToLowerInvariant()) 'observer controls receipt SHA-256 mismatch';$controlReceipt=Read-BoundedJson $controls;Require ([string]$controlReceipt.kind -eq 'sr0-display-workload-drain-controls-r10' -and [string]$controlReceipt.status -eq 'passed-source-controls' -and [bool]$controlReceipt.nativeQualificationClaim -eq $false) 'observer controls receipt invalid';Require ([string]$controlReceipt.helperSha256 -ceq ([string]$plan.sourcePins.drainHelper).ToLowerInvariant()) 'observer controls helper pin mismatch';Require (Test-Path -LiteralPath $transport -PathType Leaf) 'observer transport helper missing';Require ((Hash $transport) -ceq $TransportHelperSha256.ToLowerInvariant()) 'observer transport helper SHA-256 mismatch';$factoryPrefix=(Full ([string]$plan.factoryRoot)).TrimEnd('\')+'\';Require ($output.StartsWith($factoryPrefix,[StringComparison]::OrdinalIgnoreCase)) 'observer receipt must stay in factory root';Require (-not(Test-Path -LiteralPath $output)) 'observer receipt must be fresh';$outputParent=Split-Path -Parent $output;if(-not(Test-Path -LiteralPath $outputParent -PathType Container)){[IO.Directory]::CreateDirectory($outputParent)|Out-Null};$runRoot=Full ([string]$plan.runRoot);Require (Test-Path -LiteralPath $runRoot -PathType Container) 'observer run root missing';Require (@(Get-ChildItem -LiteralPath $runRoot -Force).Count -eq 0) 'observer run root must be fresh';
  $preflightText=& $preflight -StageRoot $stage | Out-String;$preflightSucceeded=$?;Require $preflightSucceeded 'observer production preflight failed';$preflightReceipt=$preflightText|ConvertFrom-Json;Require ([string]$preflightReceipt.status -eq 'passed-source-preflight' -and [string]$preflightReceipt.planSha256 -ceq $planSha) 'observer preflight receipt invalid'
  Add-Type -Path $transport;$job=[Sr0RootTransportJobV1]::CreateCurrentProcess();$initial=$job.Query();Require ($initial.ActiveCount -eq 1) 'observer transport initial self-only proof missing';Require ($initial.LimitFlags -eq [Sr0RootTransportJobV1]::JobMemoryOnlyFlags -and $initial.LimitBytes -eq [Sr0RootTransportJobV1]::BudgetBytes) 'observer transport memory proof missing'
  $schedule=[ordered]@{WorkerPath=[string]$plan.workerPath;LauncherHelperPath=[string]$plan.launcherHelperPath;CollectorPath=[string]$plan.collectorPath;CoordinatorPath=[string]$plan.coordinatorPath;WrapperPath=[string]$plan.wrapperPath;ManifestPath=[string]$plan.manifestPath;Base=[string]$plan.base;ControlRoot=[string]$plan.controlRoot;ControlReceiptRoot=[string]$plan.controlReceiptRoot;RequiredControlReceipts=[string[]]$plan.requiredControlReceipts;FrozenTaskPath=[string]$plan.frozenTaskPath;DrainTaskPath=[string]$plan.drainTaskPath;HelperPath=[string]$plan.helperPath;DrainHelperPath=[string]$plan.drainHelperPath;ParserPath=[string]$plan.parserPath;IdentityHelperPath=[string]$plan.identityHelperPath;WorkloadExe=[string]$plan.workloadExe;RendererDll=[string]$plan.rendererDll;PresentMonExe=[string]$plan.presentMonExe;FrozenTaskSha256=[string]$plan.sourcePins.frozenTask;DrainTaskSha256=[string]$plan.sourcePins.drainTask;HelperSha256=[string]$plan.sourcePins.helper;DrainHelperSha256=[string]$plan.sourcePins.drainHelper;ParserSha256=[string]$plan.sourcePins.parser;IdentityHelperSha256=[string]$plan.sourcePins.identityHelper;WorkerSha256=[string]$plan.sourcePins.worker;LauncherHelperSha256=[string]$plan.sourcePins.launcherHelper;CollectorSha256=[string]$plan.sourcePins.collector;CoordinatorSha256=[string]$plan.sourcePins.coordinator;WrapperSha256=[string]$plan.sourcePins.wrapper;WorkloadExeSha256=[string]$plan.sourcePins.workloadExe;RendererDllSha256=[string]$plan.sourcePins.rendererDll;PresentMonSha256=[string]$plan.sourcePins.presentMonExe;TaskName=[string]$plan.taskName;Tag=[string]$plan.tag;RunRoot=$runRoot;LockPath=[string]$plan.lockPath;Warmup=10;Measure=60;Rows=200;KeyRate=10}
  $powershell=Join-Path $PSHOME 'powershell.exe';$schedulePath=Full ([string]$plan.schedulePath);$scheduleArgs=@('-NoProfile','-ExecutionPolicy','Bypass','-WindowStyle','Hidden','-File',$schedulePath);foreach($pair in $schedule.GetEnumerator()){$scheduleArgs+=('-'+[string]$pair.Key);$scheduleArgs+=([string]$pair.Value)};$psi=New-Object Diagnostics.ProcessStartInfo;$psi.FileName=$powershell;$psi.Arguments=(($scheduleArgs|ForEach-Object{Quote ([string]$_)}) -join ' ');$psi.WorkingDirectory=Full ([string]$plan.base);$psi.UseShellExecute=$false;$psi.CreateNoWindow=$true;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true;$scheduleStartedAt=[DateTimeOffset]::UtcNow;$scheduleProcess=[Diagnostics.Process]::Start($psi);Require ($null -ne $scheduleProcess) 'observer schedule process did not start';$scheduleHandle=$scheduleProcess.Handle;Require ($scheduleHandle -ne [IntPtr]::Zero) 'observer original schedule handle missing';$scheduleHandleAcquired=$true;$stdoutPath=$output+'.schedule.stdout.bin';$stderrPath=$output+'.schedule.stderr.bin';Require (-not(Test-Path -LiteralPath $stdoutPath) -and -not(Test-Path -LiteralPath $stderrPath)) 'observer schedule streams must be fresh';$stdoutState=[Sr0RootTransportJobV1]::StartBoundedDrain($scheduleProcess.StandardOutput.BaseStream,$stdoutPath,8388608);$stderrState=[Sr0RootTransportJobV1]::StartBoundedDrain($scheduleProcess.StandardError.BaseStream,$stderrPath,8388608)
  while(-not $scheduleProcess.HasExited -and $watch.Elapsed.TotalSeconds -lt $DeadlineSeconds){if($stdoutState.CapExceeded -or $stderrState.CapExceeded){throw 'observer schedule output cap exceeded'};Start-Sleep -Milliseconds 250};Require $scheduleProcess.HasExited 'observer schedule parent exceeded deadline';$scheduleTerminal=[Sr0RootTransportJobV1]::Terminal($scheduleHandle,[ref]$scheduleRaw);$scheduleSigned=[Sr0RootTransportJobV1]::SignedDword($scheduleRaw);$scheduleExit=[int64]$scheduleProcess.ExitCode;$scheduleExitIdentity=$scheduleTerminal -and $scheduleSigned -eq $scheduleExit;Require $scheduleExitIdentity 'observer schedule parent kernel/.NET identity mismatch';Require ($scheduleExit -eq 0) "observer schedule parent exit was nonzero: $scheduleExit";$drainWatch=[Diagnostics.Stopwatch]::StartNew();while(((-not $stdoutState.Completed)-or(-not $stderrState.Completed)) -and $drainWatch.ElapsedMilliseconds -lt 10000){Start-Sleep -Milliseconds 25};Require ($stdoutState.Completed -and $stderrState.Completed -and -not $stdoutState.Error -and -not $stderrState.Error -and -not $stdoutState.CapExceeded -and -not $stderrState.CapExceeded) 'observer schedule streams did not seal';$scheduleProcess.StandardOutput.Dispose();$scheduleProcess.StandardError.Dispose();$streamsSealed=$true;$stdoutProof=StreamProof $stdoutPath;$stderrProof=StreamProof $stderrPath
  $launcherPath=Full (Join-Path $runRoot 'launcher-receipt.json');$collectorPath=Full (Join-Path $runRoot 'collector-receipt.json');$coordinatorPath=Full (Join-Path $runRoot 'coordinator-verdict.json');$releaseDeadline=$DeadlineSeconds*1000;while($watch.ElapsedMilliseconds -lt $releaseDeadline){if((Test-Path -LiteralPath $launcherPath -PathType Leaf) -and (Test-Path -LiteralPath $collectorPath -PathType Leaf) -and (Test-Path -LiteralPath $coordinatorPath -PathType Leaf)){try{$launcher=Read-BoundedJson $launcherPath;$collector=Read-BoundedJson $collectorPath;$coordinator=Read-BoundedJson $coordinatorPath;if([string]$coordinator.taskName -ceq [string]$plan.taskName -and [string]$coordinator.status -eq 'passed' -and [bool]$coordinator.parentCertificatePresent -and [bool]$coordinator.parentKernelTerminal -and [bool]$coordinator.lockOwnerObserved -and [bool]$collector.lockReleased -and [bool]$collector.releaseAllowed -and [bool]$collector.parentOriginalHandleRetained -and [bool]$collector.presentMonStreamsSealed -and [bool]$collector.activeSelfOnly -and -not [bool]$collector.timedOut -and -not [bool]$collector.outputExceeded -and [bool]$launcher.aggregateDescendantsQuiesced -and [int64]$launcher.aggregateActiveAfter -eq 1){break}}catch{}};Start-Sleep -Seconds 1};Require ($null -ne $coordinator -and [string]$coordinator.taskName -ceq [string]$plan.taskName -and [string]$coordinator.status -eq 'passed' -and [bool]$coordinator.parentCertificatePresent -and [bool]$coordinator.parentKernelTerminal -and [bool]$coordinator.lockOwnerObserved) 'observer coordinator terminal proof incomplete';Require ($null -ne $collector -and [bool]$collector.lockReleased -and [bool]$collector.releaseAllowed) 'observer did not see collector terminal release';Require ([bool]$collector.parentOriginalHandleRetained -and [bool]$collector.activeSelfOnly -and [bool]$collector.presentMonStreamsSealed) 'observer release proof incomplete';Require ($null -ne $launcher -and [bool]$launcher.aggregateDescendantsQuiesced -and [int64]$launcher.aggregateActiveAfter -eq 1) 'observer launcher self-only proof incomplete';$taskDeadline=[int64]$DeadlineSeconds*1000;while($watch.ElapsedMilliseconds -lt $taskDeadline){$task=$null;try{$task=Get-ScheduledTask -TaskName ([string]$plan.taskName) -ErrorAction Stop}catch{$message=[string]$_.Exception.Message;if($message -match '(?i)cannot find|not found|does not exist'){$schedulerState='Absent';$schedulerRunning=$false;$schedulerTerminal=$true;break};throw "observer scheduled-task query failed: $message"};if($null -eq $task){$schedulerState='Absent';$schedulerRunning=$false;$schedulerTerminal=$true;break};$tasks=@($task);Require ($tasks.Count -eq 1) 'observer scheduled-task identity was not unique';$schedulerState=[string]$tasks[0].State;$schedulerRunning=($schedulerState -eq 'Running' -or $schedulerState -eq 'Queued');if(-not $schedulerRunning){$schedulerTerminal=$true;break};Start-Sleep -Seconds 1};Require $schedulerTerminal "observer scheduled task did not reach terminal state: $schedulerState";$final=$job.WaitForOnlyCurrent([uint32][Math]::Min(30000,[Math]::Max(0,($DeadlineSeconds*1000)-$watch.ElapsedMilliseconds)));Require ($final.ActiveCount -eq 1) 'observer transport final self-only proof missing';$cleanupProof=$true;$status='passed-observer'
} catch { $failure=$_.Exception.Message } finally {
  if($scheduleProcess){try{if(-not $scheduleProcess.HasExited -and $job){$job.TerminateOwnedChildren(1,15000)|Out-Null};if(-not $scheduleProcess.HasExited){[void]$scheduleProcess.WaitForExit(5000)};if($scheduleHandleAcquired){$scheduleTerminal=[Sr0RootTransportJobV1]::Terminal($scheduleHandle,[ref]$scheduleRaw);$scheduleSigned=[Sr0RootTransportJobV1]::SignedDword($scheduleRaw);if($scheduleProcess.HasExited){$scheduleExit=[int64]$scheduleProcess.ExitCode};$scheduleExitIdentity=$scheduleTerminal -and $scheduleExit -ne $null -and $scheduleSigned -eq $scheduleExit}}catch{if(-not $failure){$failure=$_.Exception.Message}}}
  if($job){try{$beforeCleanup=$job.Query();if($beforeCleanup.ActiveCount -gt 1){$cleanup=$job.TerminateOwnedChildren(1,[uint32][Math]::Min(15000,[Math]::Max(0,($DeadlineSeconds*1000)-$watch.ElapsedMilliseconds)))};$final=$job.WaitForOnlyCurrent([uint32][Math]::Min(30000,[Math]::Max(0,($DeadlineSeconds*1000)-$watch.ElapsedMilliseconds)));$cleanupProof=($null -ne $final -and $final.ActiveCount -eq 1);if(-not $cleanupProof -and -not $failure){$failure='observer transport cleanup did not prove self-only'}}catch{if(-not $failure){$failure=$_.Exception.Message}}}
  $receipt=[ordered]@{kind='sr0-display-selfjob-v4-native-observer-r10b';status=if($status -eq 'passed-observer' -and $null -eq $failure){'passed-observer'}else{'held'};planPath=Full $PlanPath;planSha256=if($plan){$planSha}else{$null};preflightPath=$preflight;preflightSha256=$ExpectedPreflightSha256.ToLowerInvariant();controlsReceiptPath=$controls;controlsReceiptSha256=$ExpectedControlsReceiptSha256.ToLowerInvariant();transportHelperPath=$transport;transportHelperSha256=$TransportHelperSha256.ToLowerInvariant();scheduleOriginalHandleAcquired=$scheduleHandleAcquired;scheduleTerminal=$scheduleTerminal;scheduleExitRaw=$scheduleRaw;scheduleExitSigned=$scheduleSigned;scheduleExitDotnet=$scheduleExit;scheduleExitIdentity=$scheduleExitIdentity;scheduleStreamsSealed=$streamsSealed;scheduleStdout=if($stdoutProof){$stdoutProof}else{$null};scheduleStderr=if($stderrProof){$stderrProof}else{$null};launcherStatus=if($launcher){$launcher.status}else{$null};launcherAggregateActiveAfter=if($launcher){$launcher.aggregateActiveAfter}else{$null};launcherSelfOnly=if($launcher){$launcher.aggregateDescendantsQuiesced}else{$false};coordinatorStatus=if($coordinator){$coordinator.status}else{$null};coordinatorParentCertificatePresent=if($coordinator){$coordinator.parentCertificatePresent}else{$false};coordinatorParentKernelTerminal=if($coordinator){$coordinator.parentKernelTerminal}else{$false};coordinatorLockOwnerObserved=if($coordinator){$coordinator.lockOwnerObserved}else{$false};collectorStatus=if($collector){$collector.status}else{$null};collectorParentOriginalHandleRetained=if($collector){$collector.parentOriginalHandleRetained}else{$false};collectorLockReleased=if($collector){$collector.lockReleased}else{$false};collectorReleaseAllowed=if($collector){$collector.releaseAllowed}else{$false};collectorActiveSelfOnly=if($collector){$collector.activeSelfOnly}else{$false};collectorStreamsSealed=if($collector){$collector.presentMonStreamsSealed}else{$false};schedulerState=$schedulerState;schedulerRunning=$schedulerRunning;transportInitial=if($initial){$initial}else{$null};transportFinal=if($final){$final}else{$null};transportSelfOnly=if($final){$final.ActiveCount -eq 1}else{$false};transportCleanupAttempted=if($cleanup){$cleanup.Attempted}else{$false};transportCleanupBefore=if($cleanup){$cleanup.BeforeCount}else{$null};transportCleanupAfter=if($cleanup){$cleanup.AfterCount}else{$null};transportCleanupTerminated=if($cleanup){$cleanup.TerminatedCount}else{$null};transportCleanupOpenFailed=if($cleanup){$cleanup.OpenFailedCount}else{$null};transportCleanupSelfOnly=if($cleanup){$cleanup.SelfOnly}else{$cleanupProof};transportCleanupProof=$cleanupProof;schedulerTerminal=$schedulerTerminal;elapsedMilliseconds=$watch.ElapsedMilliseconds;deadlineSeconds=$DeadlineSeconds;nativeQualificationClaim=$false;failure=$failure;checkedAt=[DateTimeOffset]::UtcNow.ToString('o')};try{Write-FreshJson $output $receipt}catch{if(-not $failure){$failure=$_.Exception.Message}};if($scheduleProcess){try{$scheduleProcess.Dispose()}catch{}};if($job){try{$job.Dispose()}catch{}} }
if($status -eq 'passed-observer' -and $null -eq $failure){exit 0}else{exit 1}
